{
  "headline": "Carbamazepine 200 mg extended-release tablets are not on FDA's shortage list as of 2026-10-21; supply traces to a registered plant (Umedica Laboratories Pvt. Ltd., FEI 3008460260) with VAI inspections in 2015, 2019, and 2024",
  "headline_cites": ["D3", "E7", "E4", "E5", "E6"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows carbamazepine is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "The product label for NDC 72603088701 identifies Umedica Laboratories Pvt. Ltd. (FEI 3008460260) as the registered manufacturing plant.",
      "cites": ["E7"]
    },
    {
      "text": "FDA inspection records for that plant show three VAI classifications: inspection 953634 ending 2015-10-09, inspection 1099875 ending 2019-07-05, and inspection 1234389 ending 2024-03-29.",
      "cites": ["E4", "E5", "E6"]
    },
    {
      "text": "No FDA regulatory action (warning letter, import alert, or OAI classification) is recorded for this plant in the provided evidence.",
      "cites": ["E4", "E5", "E6"]
    },
    {
      "text": "A separate FDA shortage entry notes Takeda Pharmaceuticals USA Inc. plans to discontinue carbamazepine extended-release capsules (NDC 54092-171-12) with an initial posting date of 2025-12-19, but this is a different dosage form and manufacturer.",
      "cites": ["E8"]
    },
    {
      "text": "Corvale East holds 70 tablets (9.2 days on hand) and Corvale General holds 153 tablets (19.9 days on hand) of the same NDC 72603088701 product.",
      "cites": ["D1", "D2", "E1", "E2"]
    },
    {
      "text": "The ranked transfer option moves 37 tablets from Corvale General to Corvale East, leaving the sender with 15 days and the receiver with 14 days of supply.",
      "cites": ["D4"]
    }
  ]
}
